-- Cuentas base de evaluación: no reemplaza usuarios existentes.
SET @dept=(SELECT id FROM departamentos WHERE nombre='Departamento de prueba');
-- Seed de desarrollo, explícito y repetible; no es una migración de producción.
-- Credenciales iguales a las cuentas originales de demostración (BCrypt).
SET @actor=(SELECT id FROM usuarios WHERE correo='coordinacion@demo.example');
SET @dept=(SELECT id FROM departamentos WHERE nombre='Departamento de prueba');
SET @carrera=(SELECT id FROM carreras WHERE clave='DEMO-SIS');
SET @periodo=(SELECT id FROM periodos_academicos WHERE clave='DEMO-2026-2');
SET @motivo=(SELECT id FROM motivos_reporte WHERE codigo='bajo_rendimiento');

-- Pareja de demostración 01
SET @tu=(SELECT id FROM usuarios WHERE correo='tutor@demo.example');
SET @eu=(SELECT id FROM usuarios WHERE correo='estudiante@demo.example');
SET @t=(SELECT id FROM tutores WHERE usuario_id=@tu);
SET @e=(SELECT id FROM estudiantes WHERE usuario_id=@eu);
SET @a=(SELECT id FROM situaciones_academicas WHERE estudiante_id=@e AND periodo_id=@periodo);
SET @d=(SELECT id FROM disponibilidades_tutor WHERE tutor_id=@t AND inicio_en='2026-10-01 15:00:00' ORDER BY id LIMIT 1);
SET @s=(SELECT id FROM sesiones WHERE tema='DEMO tutoría 01' AND estudiante_id=@e ORDER BY id LIMIT 1);
SET @av=(SELECT id FROM avisos WHERE titulo='DEMO aviso 01' AND sesion_id=@s ORDER BY id LIMIT 1);
SET @chat=(SELECT c.id FROM conversaciones c WHERE c.creada_por=@tu ORDER BY c.id LIMIT 1);

